function formatMs(ms, withMs){
  ms=Math.max(0, Math.floor(ms));
  var totalSec=Math.floor(ms/1000);
  var h=Math.floor(totalSec/3600), m=Math.floor((totalSec%3600)/60), s=totalSec%60;
  var base = (h>0 ? (h<10?'0':'')+h+':' : '') + (m<10?'0':'')+m + ':' + (s<10?'0':'')+s;
  if(withMs){ var cs=Math.floor((ms%1000)/100); base += '.'+cs; }
  return base;
}
function parseCountdown(str){
  str=String(str).trim();
  if(str.indexOf(':')>=0){
    var p=str.split(':').map(function(x){ return parseInt(x,10)||0; });
    var sec=0; for(var i=0;i<p.length;i++) sec=sec*60+p[i];
    return sec;
  }
  return parseInt(str,10)||0;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { formatMs:formatMs, parseCountdown:parseCountdown };
}
if (typeof window !== 'undefined') {
  window.TimerForgePure = { formatMs:formatMs, parseCountdown:parseCountdown };
}
